class Solution {
public:
    vector<int> nextSmallerElements(const vector<int>& arr) {
        stack<int> s;
        int n = arr.size();
        vector<int> res(n, -1);

        for(int i = n - 1; i >= 0; --i){
            while(!s.empty() && s.top() >= arr[i]){
                s.pop();
            }
            if(!s.empty()){
                res[i] = s.top();
            }
            s.push(arr[i]);
        }
        return res;
    }
};
```

