class Solution {
    public List<int> NextSmallerElements(List<int> arr) {

       // Raj Thomas 25th Aug 2026 8:25PM IST
        int len = arr.Count;
        int[] result = new int[len];
        Array.Fill(result, -1);

        Stack<int> st = new Stack<int>();

        for(int i = len - 1; i >= 0; i--) {

            if(st.Count == 0) {
                result[i] = -1;
                st.Push(arr[i]);
            }
            else {
                while(st.Count > 0) {
                    int top = st.Peek();
                    if(top < arr[i]) {
                        result[i] = top;
                        break;
                    }
                    else {
                        st.Pop();
                    }

                }

                st.Push(arr[i]);
            }

        }

        return result.ToList();

    }
}
